<?php require_once __DIR__.'/../includes/attendance.php';require_login();post_guard();
$id=(int)($_GET['id']??$_SESSION['eid']);$role=$_SESSION['role'];
$s=$pdo->prepare('SELECT e.*,d.name dn,po.name pn,m.full_name mn,u.role FROM employees e LEFT JOIN departments d ON d.id=e.department_id LEFT JOIN positions po ON po.id=e.position_id LEFT JOIN employees m ON m.id=e.manager_id LEFT JOIN users u ON u.employee_id=e.id WHERE e.id=?');$s->execute([$id]);$e=$s->fetch();
if(!$e||($role==='employee'&&$id!==(int)$_SESSION['eid'])||($role==='manager'&&$id!==(int)$_SESSION['eid']&&(int)$e['manager_id']!==(int)$_SESSION['eid'])){http_response_code(403);error_page(403,'غير مصرح لك بعرض هذا الملف','يمكنك عرض ملفك الشخصي، وللمديرين ملفات فريقهم فقط.');}
if($_SERVER['REQUEST_METHOD']==='POST'&&$role==='admin'&&($_POST['do']??'')==='regen'){
 $pdo->prepare('UPDATE employee_qr_tokens SET is_active=0 WHERE employee_id=?')->execute([$id]);
 $pdo->prepare('INSERT INTO employee_qr_tokens(employee_id,token) VALUES(?,?)')->execute([$id,bin2hex(random_bytes(32))]);
 audit('qr_regenerate',$e['employee_code']);flash('تم إنشاء رمز QR جديد وإبطال القديم.');header("Location: view.php?id=$id");exit;}
$t=$pdo->prepare('SELECT token FROM employee_qr_tokens WHERE employee_id=? AND is_active=1 ORDER BY id DESC LIMIT 1');$t->execute([$id]);$token=$t->fetchColumn();
if(!$token&&$role==='admin'){$token=bin2hex(random_bytes(32));$pdo->prepare('INSERT INTO employee_qr_tokens(employee_id,token) VALUES(?,?)')->execute([$id,$token]);audit('qr_generate',$e['employee_code']);}
if($role==='manager'&&$id!==(int)$_SESSION['eid'])$token=null;
$qrurl=$token?make_qr_url($token):'';$localhost=preg_match('/^(localhost|127\.|\[::1\])/',$_SERVER['HTTP_HOST']??'')&&!trim((string)setting('public_url'));
$att=$pdo->prepare('SELECT * FROM attendance WHERE employee_id=? ORDER BY work_date DESC LIMIT 10');$att->execute([$id]);
$bal=$pdo->prepare('SELECT b.*,t.name FROM leave_balances b JOIN leave_types t ON t.id=b.leave_type_id WHERE b.employee_id=? AND b.year=YEAR(CURDATE())');$bal->execute([$id]);
$log=$pdo->prepare('SELECT a.* FROM audit_logs a JOIN users u ON u.id=a.user_id WHERE u.employee_id=? ORDER BY a.id DESC LIMIT 10');$log->execute([$id]);
$SA=['present'=>'حاضر','late'=>'متأخر','absent'=>'غائب','half_day'=>'نصف يوم','on_leave'=>'في إجازة','holiday'=>'عطلة رسمية','weekend'=>'عطلة أسبوعية'];
page_start('ملف الموظف');
$rq=$pdo->prepare('SELECT r.*,t.name tn FROM leave_requests r JOIN leave_types t ON t.id=r.leave_type_id WHERE r.employee_id=? ORDER BY r.id DESC LIMIT 20');$rq->execute([$id]);$rq=$rq->fetchAll();
$ah=$pdo->prepare('SELECT approver_role,action,note,acted_at FROM leave_approvals WHERE request_id=? ORDER BY id');$cnt=array_count_values(array_column($rq,'status'));
$self=$id===(int)$_SESSION['eid'];?>
