<?php if($role==='admin'):?><form method="post" style="display:inline" data-confirm="سيصبح الرمز القديم غير صالح. متابعة؟" data-confirm-title="إعادة إنشاء الرمز" data-confirm-ok="إعادة الإنشاء" data-confirm-tone="danger"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="do" value="regen"><button class="btn danger"><?=ic('refresh')?>إعادة إنشاء الرمز</button></form><?php endif;?></p></div>
